-- 0002: Better Auth (anonymous + passkey) and app tables rebuilt with ON DELETE CASCADE.
-- Safe because no API wrote to the 0001 tables before this migration (all empty).
PRAGMA defer_foreign_keys = true;

DROP TABLE IF EXISTS push_sub;
DROP TABLE IF EXISTS postcard;
DROP TABLE IF EXISTS stamp;
DROP TABLE IF EXISTS companion;
DROP TABLE IF EXISTS camp_item;
DROP TABLE IF EXISTS meal;
DROP TABLE IF EXISTS txn;
DROP TABLE IF EXISTS wallet;
DROP TABLE IF EXISTS traveler;
DROP TABLE IF EXISTS leg;
DROP TABLE IF EXISTS journey;
DROP TABLE IF EXISTS user;

-- Better Auth (generated by scripts/auth-schema.mjs)
create table "user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" integer not null, "image" text, "createdAt" date not null, "updatedAt" date not null, "isAnonymous" integer, "homeCurrency" text);
create table "session" ("id" text not null primary key, "expiresAt" date not null, "token" text not null unique, "createdAt" date not null, "updatedAt" date not null, "ipAddress" text, "userAgent" text, "userId" text not null references "user" ("id") on delete cascade);
create table "account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" date, "refreshTokenExpiresAt" date, "scope" text, "password" text, "createdAt" date not null, "updatedAt" date not null);
create table "verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" date not null, "createdAt" date not null, "updatedAt" date not null);
create table "passkey" ("id" text not null primary key, "name" text, "publicKey" text not null, "userId" text not null references "user" ("id") on delete cascade, "credentialID" text not null, "counter" integer not null, "deviceType" text not null, "backedUp" integer not null, "transports" text, "createdAt" date, "aaguid" text);
create index "session_userId_idx" on "session" ("userId");
create index "account_userId_idx" on "account" ("userId");
create index "verification_identifier_idx" on "verification" ("identifier");
create index "passkey_userId_idx" on "passkey" ("userId");
create index "passkey_credentialID_idx" on "passkey" ("credentialID");

-- App tables
CREATE TABLE journey (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  started_at INTEGER NOT NULL,
  time_scale REAL NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'finished', 'abandoned')),
  next_notify_at INTEGER,
  last_seen_at INTEGER,
  created_at INTEGER NOT NULL
);
CREATE INDEX idx_journey_user ON journey(user_id, status);
CREATE UNIQUE INDEX idx_journey_one_active ON journey(user_id) WHERE status = 'active';
CREATE INDEX idx_journey_notify ON journey(next_notify_at) WHERE status = 'active';

CREATE TABLE leg (
  journey_id TEXT NOT NULL REFERENCES journey(id) ON DELETE CASCADE,
  seq INTEGER NOT NULL,
  from_place TEXT NOT NULL,
  to_place TEXT NOT NULL,
  mode TEXT NOT NULL,
  polyline_key TEXT,
  distance_m REAL NOT NULL,
  PRIMARY KEY (journey_id, seq)
);

CREATE TABLE traveler (
  journey_id TEXT PRIMARY KEY REFERENCES journey(id) ON DELETE CASCADE,
  name TEXT NOT NULL DEFAULT '마치',
  level INTEGER NOT NULL DEFAULT 1,
  xp REAL NOT NULL DEFAULT 0,
  appearance_json TEXT NOT NULL DEFAULT '{}',
  culture_tags_json TEXT NOT NULL DEFAULT '{}',
  stat_stamina REAL NOT NULL DEFAULT 70,
  stat_mood REAL NOT NULL DEFAULT 70,
  stat_curiosity REAL NOT NULL DEFAULT 50,
  stat_culture REAL NOT NULL DEFAULT 50,
  stats_at INTEGER NOT NULL
);

CREATE TABLE wallet (
  journey_id TEXT NOT NULL REFERENCES journey(id) ON DELETE CASCADE,
  currency TEXT NOT NULL,
  balance REAL NOT NULL DEFAULT 0,
  PRIMARY KEY (journey_id, currency)
);

CREATE TABLE txn (
  id TEXT PRIMARY KEY,
  journey_id TEXT NOT NULL REFERENCES journey(id) ON DELETE CASCADE,
  ts INTEGER NOT NULL,
  type TEXT NOT NULL,
  currency TEXT NOT NULL,
  amount REAL NOT NULL,
  ref_id TEXT
);
CREATE INDEX idx_txn_journey ON txn(journey_id, ts);

CREATE TABLE meal (
  id TEXT PRIMARY KEY,
  journey_id TEXT NOT NULL REFERENCES journey(id) ON DELETE CASCADE,
  ts_utc INTEGER NOT NULL,
  local_ts TEXT NOT NULL,
  dish_id TEXT NOT NULL,
  price REAL NOT NULL,
  auto INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_meal_journey ON meal(journey_id, ts_utc);

CREATE TABLE camp_item (
  id TEXT PRIMARY KEY,
  journey_id TEXT NOT NULL REFERENCES journey(id) ON DELETE CASCADE,
  product_id TEXT NOT NULL,
  slot TEXT,
  x REAL,
  y REAL,
  acquired_at INTEGER NOT NULL
);

CREATE TABLE companion (
  id TEXT PRIMARY KEY,
  journey_id TEXT NOT NULL REFERENCES journey(id) ON DELETE CASCADE,
  species TEXT NOT NULL,
  met_region TEXT,
  met_at INTEGER NOT NULL
);

CREATE TABLE stamp (
  journey_id TEXT NOT NULL REFERENCES journey(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,
  key TEXT NOT NULL,
  ts INTEGER NOT NULL,
  PRIMARY KEY (journey_id, kind, key)
);

CREATE TABLE postcard (
  id TEXT PRIMARY KEY,
  journey_id TEXT NOT NULL REFERENCES journey(id) ON DELETE CASCADE,
  ts INTEGER NOT NULL,
  lat REAL NOT NULL,
  lng REAL NOT NULL,
  text TEXT,
  r2_key TEXT
);

CREATE TABLE push_sub (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  endpoint TEXT NOT NULL UNIQUE,
  keys_json TEXT NOT NULL
);
